#include "dfs/service/storage_node_rpc.hpp"
#include "dfs/storage/chunk_store.hpp"
#include <gtest/gtest.h>
#include <chrono>
#include <filesystem>
#include <fstream>
#include <memory>
#include <string>
#include <vector>
namespace {
class ReplicaRepairTest:public ::testing::Test{
protected:
 void SetUp()override{const auto stamp=std::chrono::steady_clock::now().time_since_epoch().count();root_=std::filesystem::temp_directory_path()/("dfs-repair-test-"+std::to_string(stamp));std::filesystem::create_directories(root_);}
 void TearDown()override{for(auto& s:servers_)if(s)s->stop();std::error_code ignored;std::filesystem::remove_all(root_,ignored);}
 std::filesystem::path root_;std::vector<std::unique_ptr<dfs::StorageNode>> nodes_;std::vector<std::unique_ptr<dfs::StorageNodeRpcServer>> servers_;std::vector<dfs::StorageNodeEndpoint> endpoints_;
 static std::vector<std::byte> bytes(const std::string& v){std::vector<std::byte>d(v.size());for(std::size_t i=0;i<v.size();++i)d[i]=static_cast<std::byte>(static_cast<unsigned char>(v[i]));return d;}
 bool add_nodes(){for(const std::string id:{"node-a","node-b","node-c"}){nodes_.push_back(std::make_unique<dfs::StorageNode>(dfs::StorageNodeConfig{id,root_/id,1024U}));auto init=nodes_.back()->initialize();if(!init)return false;servers_.push_back(std::make_unique<dfs::StorageNodeRpcServer>(*nodes_.back()));auto started=servers_.back()->start();if(!started)return false;endpoints_.push_back({id,"127.0.0.1",servers_.back()->port()});}return true;}
 dfs::DistributedChunkService cluster()const{return dfs::DistributedChunkService(endpoints_,3U);}
 std::filesystem::path chunk_path(const std::string& id,const std::string& chunk)const{return root_/id/"chunks"/(chunk+".chunk");}
 bool damage_payload(const std::string& id,const std::string& chunk){std::fstream stream(chunk_path(id,chunk),std::ios::in|std::ios::out|std::ios::binary);if(!stream)return false;constexpr std::streamoff header=71;stream.seekg(header);char value=0;stream.read(&value,1);if(!stream)return false;value=static_cast<char>(value^0x5a);stream.seekp(header);stream.write(&value,1);stream.flush();return static_cast<bool>(stream);}
 bool divergent_valid(const std::string& id,const std::string& chunk){dfs::ChunkStore store(root_/id/"chunks");return static_cast<bool>(store.put(chunk,bytes("different-valid-payload")));}
};
TEST_F(ReplicaRepairTest,AuditReportsHealthyReplicas){ASSERT_TRUE(add_nodes());ASSERT_TRUE(cluster().put_chunk("audit",bytes("same")));auto report=dfs::ReplicaRepairService(endpoints_,3U).audit_chunk("audit");ASSERT_TRUE(report)<<report.error();EXPECT_TRUE(report.value().complete());EXPECT_EQ(report.value().verified_node_ids.size(),3U);EXPECT_TRUE(report.value().repaired_node_ids.empty());EXPECT_TRUE(report.value().unresolved_node_ids.empty());}
TEST_F(ReplicaRepairTest,RepairsMissingReplicaAndVerifiesReadBack){ASSERT_TRUE(add_nodes());ASSERT_TRUE(cluster().put_chunk("missing-replica",bytes("recover-me")));auto targets=cluster().placement("missing-replica");ASSERT_TRUE(targets);const auto target=targets.value()[1].node_id;ASSERT_TRUE(std::filesystem::remove(chunk_path(target,"missing-replica")));auto report=dfs::ReplicaRepairService(endpoints_,3U).repair_chunk("missing-replica");ASSERT_TRUE(report)<<report.error();EXPECT_TRUE(report.value().complete());ASSERT_EQ(report.value().repaired_node_ids.size(),1U);EXPECT_EQ(report.value().repaired_node_ids[0],target);for(const auto& ep:endpoints_){auto fetched=dfs::StorageNodeRpcClient(ep).get_chunk("missing-replica");ASSERT_TRUE(fetched)<<fetched.error();EXPECT_EQ(fetched.value(),bytes("recover-me"));}}
TEST_F(ReplicaRepairTest,RepairsPayloadChecksumCorruption){ASSERT_TRUE(add_nodes());ASSERT_TRUE(cluster().put_chunk("corrupt-replica",bytes("recover-me")));auto targets=cluster().placement("corrupt-replica");ASSERT_TRUE(targets);const auto target=targets.value()[1].node_id;ASSERT_TRUE(damage_payload(target,"corrupt-replica"));auto audit=dfs::ReplicaRepairService(endpoints_,3U).audit_chunk("corrupt-replica");ASSERT_TRUE(audit);EXPECT_FALSE(audit.value().complete());auto report=dfs::ReplicaRepairService(endpoints_,3U).repair_chunk("corrupt-replica");ASSERT_TRUE(report)<<report.error();EXPECT_TRUE(report.value().complete());ASSERT_EQ(report.value().repaired_node_ids.size(),1U);EXPECT_EQ(report.value().repaired_node_ids[0],target);}
TEST_F(ReplicaRepairTest,RepairsReadableButDivergentReplica){ASSERT_TRUE(add_nodes());ASSERT_TRUE(cluster().put_chunk("divergent",bytes("correct-payload")));auto targets=cluster().placement("divergent");ASSERT_TRUE(targets);const auto target=targets.value()[1].node_id;ASSERT_TRUE(divergent_valid(target,"divergent"));auto audit=dfs::ReplicaRepairService(endpoints_,3U).audit_chunk("divergent");ASSERT_TRUE(audit);EXPECT_FALSE(audit.value().complete());EXPECT_TRUE(std::any_of(audit.value().observations.begin(),audit.value().observations.end(),[](const auto& o){return o.health==dfs::ReplicaHealth::divergent;}));auto report=dfs::ReplicaRepairService(endpoints_,3U).repair_chunk("divergent");ASSERT_TRUE(report)<<report.error();EXPECT_TRUE(report.value().complete());ASSERT_EQ(report.value().repaired_node_ids.size(),1U);auto fetched=dfs::StorageNodeRpcClient(targets.value()[1]).get_chunk("divergent");ASSERT_TRUE(fetched);EXPECT_EQ(fetched.value(),bytes("correct-payload"));}
TEST_F(ReplicaRepairTest,ReportsUnavailableNodeWithoutFalseSuccess){ASSERT_TRUE(add_nodes());ASSERT_TRUE(cluster().put_chunk("offline",bytes("survives")));auto targets=cluster().placement("offline");ASSERT_TRUE(targets);const auto offline=targets.value()[0].node_id;for(std::size_t i=0;i<endpoints_.size();++i)if(endpoints_[i].node_id==offline)servers_[i]->stop();auto report=dfs::ReplicaRepairService(endpoints_,3U).repair_chunk("offline");ASSERT_TRUE(report)<<report.error();EXPECT_FALSE(report.value().complete());ASSERT_EQ(report.value().unresolved_node_ids.size(),1U);EXPECT_EQ(report.value().unresolved_node_ids[0],offline);}
TEST_F(ReplicaRepairTest,CannotRepairWhenAllSourcesAreLost){ASSERT_TRUE(add_nodes());ASSERT_TRUE(cluster().put_chunk("lost",bytes("payload")));for(const auto& ep:endpoints_)ASSERT_TRUE(std::filesystem::remove(chunk_path(ep.node_id,"lost")));auto report=dfs::ReplicaRepairService(endpoints_,3U).repair_chunk("lost");ASSERT_TRUE(report)<<report.error();EXPECT_FALSE(report.value().complete());EXPECT_TRUE(report.value().source_node_id.empty());EXPECT_EQ(report.value().unresolved_node_ids.size(),3U);}
}
